static z_t82_t z_t82_substring(const z_t82_t* self, uint64_t from, uint64_t to) {
    if (from > self->size || to > self->size || from > to) z_panic("substring: bounds error");
    return (z_t82_t){ .size = to - from, .data = self->data + from };
}
